import sys

def solve():
    data = list(map(int, sys.stdin.read().split()))
    idx = 0
    n, m = data[idx], data[idx + 1]
    idx += 2
    req = [0] * 101
    for _ in range(n):
        s, t, c = data[idx], data[idx + 1], data[idx + 2]
        idx += 3
        for pos in range(s, t + 1):
            req[pos] = c
    acs = []
    for _ in range(m):
        a, b, p, cost = data[idx], data[idx + 1], data[idx + 2], data[idx + 3]
        idx += 4
        acs.append((a, b, p, cost))

    ans = float('inf')
    for mask in range(1 << m):
        cool = [0] * 101
        cost = 0
        for i in range(m):
            if (mask >> i) & 1:
                a, b, p, mc = acs[i]
                cost += mc
                for pos in range(a, b + 1):
                    cool[pos] += p
        if cost < ans and all(cool[pos] >= req[pos] for pos in range(1, 101)):
            ans = cost
    print(ans)

if __name__ == "__main__":
    solve()

