#include <algorithm>
#include <climits>
#include <iostream>
#include <vector>
using namespace std;

struct AC {
    int a, b, p, m;
};

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> req(101, 0);
    for (int i = 0; i < n; i++) {
        int s, t, c;
        cin >> s >> t >> c;
        for (int x = s; x <= t; x++) req[x] = c;
    }
    vector<AC> acs(m);
    for (int i = 0; i < m; i++) {
        cin >> acs[i].a >> acs[i].b >> acs[i].p >> acs[i].m;
    }
    int ans = INT_MAX;
    for (int mask = 0; mask < (1 << m); mask++) {
        int cool[101] = {};
        int cost = 0;
        for (int i = 0; i < m; i++) {
            if ((mask >> i) & 1) {
                cost += acs[i].m;
                for (int x = acs[i].a; x <= acs[i].b; x++) cool[x] += acs[i].p;
            }
        }
        bool ok = true;
        for (int x = 1; x <= 100; x++) {
            if (cool[x] < req[x]) { ok = false; break; }
        }
        if (ok) ans = min(ans, cost);
    }
    cout << ans << '\n';
    return 0;
}

