public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        int[] req = new int[101];
        for (int i = 0; i < n; i++) {
            int s = sc.nextInt(), t = sc.nextInt(), c = sc.nextInt();
            for (int x = s; x <= t; x++) req[x] = c;
        }
        int[] a = new int[m], b = new int[m], p = new int[m], costArr = new int[m];
        for (int i = 0; i < m; i++) {
            a[i] = sc.nextInt();
            b[i] = sc.nextInt();
            p[i] = sc.nextInt();
            costArr[i] = sc.nextInt();
        }
        int ans = Integer.MAX_VALUE;
        for (int mask = 0; mask < (1 << m); mask++) {
            int[] cool = new int[101];
            int cost = 0;
            for (int i = 0; i < m; i++) {
                if (((mask >> i) & 1) == 1) {
                    cost += costArr[i];
                    for (int x = a[i]; x <= b[i]; x++) cool[x] += p[i];
                }
            }
            boolean ok = true;
            for (int x = 1; x <= 100; x++) {
                if (cool[x] < req[x]) { ok = false; break; }
            }
            if (ok) ans = Math.min(ans, cost);
        }
        System.out.println(ans);
    }
}

